-- =====================================================================
-- Struktura Grupy VIZJA – schemat bazy Supabase
-- Uruchom raz w Supabase: SQL Editor → New query → wklej całość → Run.
-- Bezpieczne do ponownego uruchomienia (nie kasuje danych).
-- =====================================================================

-- ---------- Zespół i role ----------
create table if not exists public.members (
  email      text primary key check (email = lower(email)),
  name       text not null default '',
  unit       text not null default '',
  role       text not null default 'editor' check (role in ('viewer','editor','admin')),
  created_at timestamptz not null default now()
);
comment on table public.members is 'Osoby z dostępem. viewer = podgląd i komentarze, editor = edycja, admin = edycja + zarządzanie zespołem.';

-- e-mail zalogowanej osoby (małe litery)
create or replace function public.current_email() returns text
language sql stable as $$
  select lower(coalesce(auth.jwt() ->> 'email', ''))
$$;

create or replace function public.my_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.members where email = public.current_email()
$$;

create or replace function public.is_member() returns boolean
language sql stable as $$ select public.my_role() is not null $$;

create or replace function public.can_edit() returns boolean
language sql stable as $$ select coalesce(public.my_role() in ('editor','admin'), false) $$;

create or replace function public.is_admin() returns boolean
language sql stable as $$ select coalesce(public.my_role() = 'admin', false) $$;

-- Czy na ten adres wolno wysłać link logowania (wywoływane przed zalogowaniem).
-- Gdy lista zespołu jest pusta, pierwsza osoba może się zalogować i zostaje administratorem.
create or replace function public.is_allowed_email(p_email text) returns boolean
language sql stable security definer set search_path = public as $$
  select not exists (select 1 from public.members)
      or exists (select 1 from public.members where email = lower(trim(p_email)))
$$;

-- Pierwsza zalogowana osoba przy pustej liście zespołu zostaje administratorem.
create or replace function public.claim_first_admin() returns text
language plpgsql security definer set search_path = public as $$
declare e text := public.current_email();
begin
  if e = '' then return null; end if;
  if not exists (select 1 from public.members) then
    insert into public.members(email, role) values (e, 'admin');
  end if;
  return (select role from public.members where email = e);
end $$;

-- ---------- Elementy struktury (L1–L4) ----------
create table if not exists public.nodes (
  id         text primary key,
  parent     text not null default '',
  level      smallint not null check (level between 1 and 4),
  ord        integer not null default 0,
  name       text not null,
  descr      text not null default '',
  note       text not null default '',
  decisions  jsonb not null default '[]'::jsonb,
  status     text not null default 'szkic',
  model      text not null default '',
  owner      text not null default '',
  units      jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  updated_by text not null default ''
);
create index if not exists nodes_parent_idx on public.nodes(parent);

create or replace function public.touch_node() returns trigger
language plpgsql as $$
begin
  new.updated_at := now();
  new.updated_by := public.current_email();
  return new;
end $$;
drop trigger if exists nodes_touch on public.nodes;
create trigger nodes_touch before insert or update on public.nodes
  for each row execute function public.touch_node();

-- Zmiana jednego pola realizacji w uczelni bez nadpisywania pozostałych
create or replace function public.set_unit(p_node text, p_unit text, p_field text, p_value text)
returns void language plpgsql security invoker set search_path = public as $$
begin
  if p_field not in ('who','state','note') then raise exception 'Nieznane pole: %', p_field; end if;
  update public.nodes
     set units = jsonb_set(
           coalesce(units, '{}'::jsonb),
           array[p_unit],
           coalesce(units -> p_unit, '{}'::jsonb) || jsonb_build_object(p_field, p_value),
           true)
   where id = p_node;
end $$;

-- ---------- Komentarze ----------
create table if not exists public.comments (
  id          uuid primary key default gen_random_uuid(),
  node        text not null,
  area        text not null default '',
  body        text not null check (length(body) between 1 and 5000),
  by_email    text not null default public.current_email(),
  created_at  timestamptz not null default now(),
  resolved    boolean not null default false,
  resolved_by text not null default '',
  resolved_at timestamptz
);
create index if not exists comments_node_idx on public.comments(node);

-- ---------- Historia zmian ----------
create table if not exists public.change_log (
  id        bigint generated always as identity primary key,
  node      text not null default '',
  node_name text not null default '',
  area      text not null default '',
  action    text not null default '',
  detail    text not null default '',
  by_email  text not null default public.current_email(),
  at        timestamptz not null default now()
);
create index if not exists change_log_at_idx on public.change_log(at desc);

-- ---------- Ustawienia (lista uczelni) ----------
create table if not exists public.settings (
  key   text primary key,
  value jsonb not null
);

-- ---------- Uprawnienia (Row Level Security) ----------
alter table public.members    enable row level security;
alter table public.nodes      enable row level security;
alter table public.comments   enable row level security;
alter table public.change_log enable row level security;
alter table public.settings   enable row level security;

drop policy if exists members_read  on public.members;
drop policy if exists members_write on public.members;
create policy members_read  on public.members for select to authenticated using (public.is_member());
create policy members_write on public.members for all    to authenticated using (public.is_admin()) with check (public.is_admin());
drop policy if exists members_self on public.members;
create policy members_self  on public.members for update to authenticated using (email = public.current_email()) with check (email = public.current_email() and role = public.my_role());

drop policy if exists nodes_read  on public.nodes;
drop policy if exists nodes_write on public.nodes;
create policy nodes_read  on public.nodes for select to authenticated using (public.is_member());
create policy nodes_write on public.nodes for all    to authenticated using (public.can_edit()) with check (public.can_edit());

drop policy if exists comments_read   on public.comments;
drop policy if exists comments_insert on public.comments;
drop policy if exists comments_update on public.comments;
drop policy if exists comments_delete on public.comments;
create policy comments_read   on public.comments for select to authenticated using (public.is_member());
create policy comments_insert on public.comments for insert to authenticated with check (public.is_member() and by_email = public.current_email());
create policy comments_update on public.comments for update to authenticated using (public.can_edit() or by_email = public.current_email()) with check (public.is_member());
create policy comments_delete on public.comments for delete to authenticated using (public.is_admin() or by_email = public.current_email());

drop policy if exists log_read   on public.change_log;
drop policy if exists log_insert on public.change_log;
create policy log_read   on public.change_log for select to authenticated using (public.is_member());
create policy log_insert on public.change_log for insert to authenticated with check (public.is_member() and by_email = public.current_email());

drop policy if exists settings_read  on public.settings;
drop policy if exists settings_write on public.settings;
create policy settings_read  on public.settings for select to authenticated using (public.is_member());
create policy settings_write on public.settings for all    to authenticated using (public.is_admin()) with check (public.is_admin());

grant execute on function public.is_allowed_email(text) to anon, authenticated;
grant execute on function public.claim_first_admin()    to authenticated;
grant execute on function public.set_unit(text,text,text,text) to authenticated;
grant execute on function public.my_role() to authenticated;

-- ---------- Zmiany na żywo (Realtime) ----------
alter table public.nodes      replica identity full;
alter table public.comments   replica identity full;
do $$
declare t text;
begin
  foreach t in array array['nodes','comments','change_log','settings','members'] loop
    if not exists (select 1 from pg_publication_tables
                   where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;

-- ---------- Domyślna lista uczelni ----------
insert into public.settings(key, value) values
  ('units', '[{"code":"UV","name":"Uniwersytet VIZJA"},{"code":"UAFM","name":"UAFM Kraków"},{"code":"UZW","name":"UZW"}]'::jsonb)
on conflict (key) do nothing;


