insert into public.nodes (id, parent, level, ord, name, descr, note, decisions, status, model, owner, units)
select id, parent, level, ord, name, descr, note, decisions, status, model, owner, units
from jsonb_to_recordset('[{"id": "it", "parent": "", "level": 1, "ord": 1, "name": "Obszar IT", "descr": "Uporządkowanie całego obszaru IT według trzech poziomów odpowiedzialności: funkcji L2, procesów L3 oraz działań operacyjnych L4. Model pokazuje, jakiego rodzaju decyzje zapadają na każdym poziomie i gdzie przebiegają granice odpowiedzialności.", "note": "Zasada organizacyjna: struktura IT może być złożona wewnętrznie, ale dla użytkownika powinna pozostać prosta. Użytkownik zgłasza problem w jednym miejscu, a wewnętrzny routing kieruje sprawę do funkcji odpowiedzialnej za dany proces.\n\nPrzykład: użytkownik zgłasza, że nie działa aplikacja rekrutacyjna. Obsługa użytkowników przyjmuje i klasyfikuje zgłoszenie. Konfiguracja → Systemy biznesowe; kod → Programowanie; serwer → Infrastruktura; podejrzenie naruszenia → Cyberbezpieczeństwo.", "decisions": ["L2 – funkcja: za co odpowiada cały obszar i jakiego rodzaju decyzje organizacyjne podejmuje.", "L3 – proces: jak konkretnie ma działać proces – zasady, standardy, terminy, wyjątki i odpowiedzialności.", "L4 – realizacja: konkretne czynności wykonywane przez zespoły i pracowników w codziennej pracy."], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it-1", "parent": "it", "level": 2, "ord": 1, "name": "Infrastruktura IT i systemy techniczne", "descr": "Zapewnienie stabilnego działania infrastruktury technicznej oraz systemów technicznych obiektów.", "note": "Funkcja zapewnia stabilne działanie infrastruktury technicznej oraz systemów technicznych obiektów. Obejmuje zarówno klasyczne elementy IT, jak serwery i sieci, jak również kontrolę dostępu, monitoring wizyjny, system kolejkowy i telefonię.", "decisions": ["Jakie technologie i standardy stosujemy.", "Co jest wspólne, a co lokalne.", "Jakie są wymagania dostępności i pojemności.", "Gdzie inwestujemy w rozwój infrastruktury."], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it-1-1", "parent": "it-1", "level": 3, "ord": 1, "name": "Serwery i wirtualizacja", "descr": "Utrzymanie serwerów fizycznych, wirtualnych i systemów operacyjnych.", "note": "", "decisions": ["Jakie systemy i wersje są wspierane.", "Jaki standard konfiguracji serwera obowiązuje.", "Kiedy serwer jest modernizowany lub wycofywany."], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it-1-1-1", "parent": "it-1-1", "level": 4, "ord": 1, "name": "Utworzenie maszyny wirtualnej", "descr": "", "note": "", "decisions": [], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it-1-1-2", "parent": "it-1-1", "level": 4, "ord": 2, "name": "Zwiększenie RAM/CPU", "descr": "", "note": "", "decisions": [], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it-1-1-3", "parent": "it-1-1", "level": 4, "ord": 3, "name": "Aktualizacja systemu operacyjnego", "descr": "", "note": "", "decisions": [], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it-1-2", "parent": "it-1", "level": 3, "ord": 2, "name": "Sieci, łączność i Wi-Fi", "descr": "LAN, WAN, Internet, VPN, segmentacja, Wi-Fi i urządzenia sieciowe.", "note": "", "decisions": ["Jak segmentujemy sieć.", "Jaką redundancję łączy zapewniamy.", "Jakie standardy Wi-Fi obowiązują w kampusach."], "status": "szkic", "model": "", "owner": "", "units": {"UV": {"who": "", "state": ""}, "UAFM": {"who": "", "state": ""}, "UZW": {"who": "", "state": ""}}}, {"id": "it